const { ethers } = require('ethers');

const data = '';

// Parse VerifiableURI
const identifier = data.slice(2, 6);
const verificationMethod = data.slice(6, 14);
const dataLength = data.slice(14, 18);
const urlHex = '0x' + data.slice(18);

console.log('Structure:');
console.log('Identifier:', identifier, '(should be 0000)');
console.log('Verification method:', verificationMethod, '(should be 00000000)');
console.log('Data length:', dataLength, '(should be 0000)');
console.log('');

try {
  const url = ethers.toUtf8String(urlHex);
  console.log('Decoded URL:');
  console.log(url);
  console.log('');
  
  // Extract base64 part
  if (url.startsWith('data:application/json;base64,')) {
    const base64 = url.replace('data:application/json;base64,', '');
    const jsonString = Buffer.from(base64, 'base64').toString('utf8');
    const json = JSON.parse(jsonString);
    console.log('Decoded JSON:');
    console.log(JSON.stringify(json, null, 2));
  }
} catch (e) {
  console.error('Error:', e.message);
}
